package br.com.catalogo;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;
class LibrarySettingsTest {
 @TempDir Path root;String oldHome,oldConfig;
 @BeforeEach void setup(){oldHome=System.getProperty("user.home");oldConfig=System.getProperty("catalogo.libraries");System.setProperty("user.home",root.resolve("user").toString());System.setProperty("catalogo.libraries",root.resolve("settings/libraries.json").toString());}
 @AfterEach void restore(){System.setProperty("user.home",oldHome);if(oldConfig==null)System.clearProperty("catalogo.libraries");else System.setProperty("catalogo.libraries",oldConfig);}
 @Test void freshInstallationDoesNotCreateLibraryUntilChosen()throws Exception{assertNull(LibrarySettings.read().active());assertFalse(Files.exists(LibrarySettings.legacy().directory()));var profile=new LibrarySettings.Profile(root.resolve("chosen/digital"),"meus-livros.db");profile.open();LibrarySettings.activate(profile);assertTrue(Files.isRegularFile(profile.file()));assertFalse(Files.exists(profile.directory().resolve("catalogo.sqlite")));assertEquals(profile,LibrarySettings.read().active());}
 @Test void opensExistingDatabaseAndSwitchesWithoutLosingMarks()throws Exception{
  var first=new LibrarySettings.Profile(root.resolve("books"),"primeiro.sqlite");var lib=first.open();var draft=new PhysicalBooks.Draft();draft.title="Livro existente";draft.notes="Preservar";PhysicalBooks.save(lib,draft);LibrarySettings.activate(first);var second=new LibrarySettings.Profile(first.directory(),"segundo.sqlite");assertTrue(second.open().books().isEmpty());LibrarySettings.activate(second);assertEquals(second,LibrarySettings.read().active());LibrarySettings.activate(first);assertEquals(1,first.open().books().size());assertEquals("Preservar",first.open().books().get(0).notes);assertEquals(2,LibrarySettings.read().profiles().size());assertEquals(first.file().toString(),new HtmlCatalog(first.open()).catalog().get("database"));
 }
 @Test void discoversLegacyLibraryAndKeepsItInHistory()throws Exception{var legacy=LibrarySettings.legacy();legacy.open();assertEquals(legacy,LibrarySettings.read().active());var other=new LibrarySettings.Profile(root.resolve("other"),"new.db");other.open();LibrarySettings.activate(other);assertTrue(LibrarySettings.read().profiles().contains(legacy));}
 @Test void validatesBankNamesAndExplicitArguments(){assertThrows(IllegalArgumentException.class,()->new LibrarySettings.Profile(root,"../other.db"));assertThrows(IllegalArgumentException.class,()->new LibrarySettings.Profile(root,"book.pdf"));var chosen=LibrarySettings.explicit(new String[]{"--library",root.toString(),"--database","chosen.db"});assertEquals(root.resolve("chosen.db"),chosen.file());}
}
